/* ---- line up valves on a P&ID ---- */
WIDGETS.pidLineUp=function(box){var V={v1:false,v2:false,v3:false,v4:false,v5:false},running=false,ok=false,wrap=el('div','tl',null,box);
 var POS={v1:[82,118,0],v2:[190,48,0],v3:[230,178,0],v4:[330,118,0],v5:[356,154,1]};
 function seg(id,d){return '<path data-s="'+id+'" d="'+d+'" stroke="var(--text)" stroke-width="3" fill="none" stroke-linejoin="round"/>'}
 function draw(){var fl=flows(),g='';
  g+='<rect x="12" y="72" width="44" height="76" rx="6" fill="var(--panel)" stroke="var(--text)" stroke-width="2"/><rect x="14" y="98" width="40" height="48" rx="4" fill="var(--blue)" opacity=".22"/><text x="34" y="66" class="dl">Tank A</text>';
  g+='<rect x="368" y="72" width="44" height="76" rx="6" fill="var(--panel)" stroke="var(--text)" stroke-width="2"/><rect x="370" y="'+(ok&&running?110:128)+'" width="40" height="'+(ok&&running?36:18)+'" rx="4" fill="var(--blue)" opacity=".22"/><text x="390" y="66" class="dl">Tank B</text>';
  g+=seg('a','M56 118H160')+seg('top','M160 118V48H214M270 48H300V118')+seg('bot','M160 118V178H300V118')+seg('out','M300 118H368')+seg('dr','M356 118V184');
  g+='<rect x="214" y="34" width="56" height="28" rx="5" fill="var(--panel)" stroke="var(--text)" stroke-width="2"/><path d="M219 54l7-14l7 14l7-14l7 14l7-14l7 14" fill="none" stroke="var(--coral)" stroke-width="2"/><text x="242" y="26" class="dl">heat exchanger</text>';
  g+='<text x="230" y="200" class="dl s">bypass</text><text x="356" y="200" class="dl s">drain</text>';
  g+='<g transform="translate(126 118)"><circle r="15" fill="'+(running?'var(--accent-bg)':'var(--panel)')+'" stroke="var(--text)" stroke-width="2"/><path d="M-5 -8L9 0L-5 8Z" fill="var(--text)"/></g><text x="126" y="148" class="dl">pump</text>';
  for(var k in POS){var p=POS[k],open=V[k];
   g+='<g class="lu" data-v="'+k+'" tabindex="0" role="button" aria-label="Valve '+k.toUpperCase()+', '+(open?'open':'shut')+'" style="cursor:pointer" transform="translate('+p[0]+' '+p[1]+')'+(p[2]?' rotate(90)':'')+'"><rect x="-16" y="-14" width="32" height="28" fill="transparent"/><path d="M-11 -8L11 8V-8L-11 8Z" fill="'+(open?'var(--panel)':'var(--text)')+'" stroke="var(--text)" stroke-width="2" stroke-linejoin="round"/></g>'+
    '<text x="'+(p[0]+(p[2]?18:0))+'" y="'+(p[1]+(p[2]?4:-14))+'" class="dl" style="font-weight:700'+(p[2]?';text-anchor:start':'')+'">'+k.toUpperCase()+'</text>';}
  wrap.innerHTML=tSvg('0 0 424 210',g);
  if(running)['a','top','bot','out','dr'].forEach(function(s){if(fl[s]){var e=wrap.querySelector('[data-s="'+s+'"]');e.setAttribute('stroke',cssv('--accent'));e.style.strokeDasharray='7 6';e.style.animation='flow 1.1s linear infinite'}});
  [].forEach.call(wrap.querySelectorAll('.lu'),function(gv){function tog(){var k=gv.getAttribute('data-v');V[k]=!V[k];if(running){running=false;m.set('Pump stopped while you moved a valve. Line up first, then start it.')}else m.set('');draw();st.textContent=state()}
   gv.addEventListener('click',tog);gv.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();tog()}})});}
 function flows(){var out=V.v4||V.v5,br=V.v2||V.v3,go=V.v1&&br&&out;return {a:go,top:go&&V.v2,bot:go&&V.v3,out:go&&V.v4,dr:go&&V.v5}}
 function state(){return 'Valves: '+['v1','v2','v3','v4','v5'].map(function(k){return k.toUpperCase()+' '+(V[k]?'open':'shut')}).join(', ')}
 var st=el('p','small',null,box),r=row(box),m=msg(box);
 btn(r,'Start pump',function(){if(!V.v1){running=false;draw();m.set('The pump has no suction: V1 is shut, so it would run dry and could be damaged.',false);return}
   if(!(V.v2||V.v3)||!(V.v4||V.v5)){running=false;draw();m.set('There\'s no path for the water. The pump would be pumping against a shut valve ("dead-headed").',false);return}
   running=true;var p=[];if(!V.v2)p.push('nothing goes through the heat exchanger');if(V.v3)p.push('some water takes the bypass through V3 and misses the heat exchanger');if(V.v5)p.push('water is going down the drain through V5');if(!V.v4)p.push('nothing reaches tank B');
   ok=!p.length;draw();m.set(ok?'Lined up correctly. Water flows from tank A, through the heat exchanger, into tank B.':'The pump is running, but '+p.join(', and ')+'.',ok)},'pri');
 btn(r,'Stop pump',function(){running=false;draw();m.set('')});
 draw();st.textContent=state();
 return {check:function(){return ok&&running?{ok:true}:{ok:false,msg:'Line the valves up, then start the pump and get water through the heat exchanger into tank B.'}}}};

/* ---- build an instrument tag ---- */
WIDGETS.tagBuilder=function(box,par){var VAR={T:'Temperature',P:'Pressure',L:'Level',F:'Flow'},FN={I:'indicator',T:'transmitter',C:'controller',A:'alarm',H:'high',L:'low'};
 var goals=par.goals||[['An instrument that shows pressure on a display',['PI']],['A level transmitter',['LT']],['A flow controller',['FC','FIC']],['An alarm that warns of high temperature',['TAH']]],gi=0,first='',rest=[];
 var tgt=el('div','mission',null,box),disp=el('div','',null,box);disp.style.cssText='display:flex;align-items:center;gap:14px;margin:10px 0;flex-wrap:wrap';
 var r1=row(box);el('label','','1. What it measures',r1);var b1={};Object.keys(VAR).forEach(function(k){b1[k]=btn(r1,k+' · '+VAR[k],function(){first=k;rest=[];upd()})});
 var r2=row(box);el('label','','2. What it does',r2);Object.keys(FN).forEach(function(k){btn(r2,k+' · '+FN[k],function(){if(!first){m.set('Pick what it measures first.',false);return}if(rest.length<3)rest.push(k);upd()})});
 var r3=row(box);btn(r3,'Clear',function(){first='';rest=[];upd()});btn(r3,'Check this tag',chk,'pri');var m=msg(box);
 function tag(){return first+rest.join('')}
 function meaning(){if(!first)return 'Pick what it measures.';var w=rest.map(function(k){return FN[k]});return VAR[first]+(w.length?' '+w.join(' '):'')}
 function upd(){tgt.innerHTML=gi<goals.length?'<b>Build the tag for:</b> '+goals[gi][0]+' <span class="small">('+(gi+1)+' of '+goals.length+')</span>':'<b>All tags built.</b> You can read instrument bubbles now.';
  for(var k in b1)b1[k].classList.toggle('on',k===first);
  disp.innerHTML='<svg viewBox="0 0 64 64" width="64" height="64" aria-hidden="true"><circle cx="32" cy="32" r="28" fill="var(--panel)" stroke="var(--text)" stroke-width="2.5"/><text x="32" y="'+(tag()?36:38)+'" text-anchor="middle" style="font:700 '+(tag().length>3?13:16)+'px ui-monospace,Consolas,monospace;fill:var(--text)">'+(tag()||'?')+'</text></svg><div><b style="font-family:var(--mono);font-size:20px">'+(tag()||'–')+'</b><br><span class="small">'+meaning()+'</span></div>'}
 function chk(){if(gi>=goals.length)return;if(!first){m.set('Build a tag first.',false);return}if(goals[gi][1].indexOf(tag())>=0){m.set('Correct: <b>'+tag()+'</b> means '+meaning().toLowerCase()+'.',true);gi++;first='';rest=[];upd()}else m.set('Not quite. <b>'+tag()+'</b> would mean '+meaning().toLowerCase()+'. Try again.',false)}
 upd();return {check:function(){return gi>=goals.length?{ok:true}:{ok:false,msg:'Build all '+goals.length+' tags first. '+(goals.length-gi)+' to go.'}}}};

/* ---- a 4 to 20 mA signal ---- */
WIDGETS.signal420=function(box,par){var lo=par.lo||0,hi=par.hi||200,u=par.u||'bar',target=par.target||150,ma=12,fault=false,hit=false;
 var tasks=el('div','mission',null,box),big=el('div','',null,box);big.style.cssText='margin:10px 0;padding:14px;border-radius:12px;text-align:center';
 var r=el('div','wrow',null,box);r.innerHTML='<label for="s420">Signal from the transmitter</label><input type="range" id="s420" min="0" max="22" step="0.5" value="12"><output></output>';var inp=r.querySelector('input'),out=r.querySelector('output');
 inp.oninput=function(){ma=+inp.value;upd()};
 function upd(){out.textContent=ma.toFixed(1)+' mA';var bad=ma<3.8||ma>20.5,val=lo+(ma-4)/16*(hi-lo);if(ma<3.8)fault=true;if(!bad&&Math.abs(val-target)<0.01)hit=true;
  big.style.background=bad?cssv('--bad-bg'):cssv('--soft');big.style.color=bad?cssv('--bad'):cssv('--text');
  big.innerHTML=bad?'<b style="font-size:22px">'+(ma<3.8?'FAULT: signal lost':'FAULT: over range')+'</b><div class="small">'+(ma<3.8?'Below 4 mA means the wire or transmitter has failed, not that the pressure is zero.':'Above 20 mA is outside the range, so the reading can\'t be trusted.')+'</div>':'<b style="font-size:28px;font-family:var(--mono)">'+(Math.round(val*10)/10)+' '+u+'</b><div class="small">Range '+lo+' to '+hi+' '+u+' · 4 mA = '+lo+', 20 mA = '+hi+'</div>';
  tasks.innerHTML='<b>Try this:</b><ul><li'+(hit?' class="ok"':'')+'>Make the display read exactly '+target+' '+u+'</li><li'+(fault?' class="ok"':'')+'>Slide right down to 0 mA to see a broken wire</li></ul>'}
 upd();return {check:function(){return hit&&fault?{ok:true}:{ok:false,msg:!hit?'Make the display read exactly '+target+' '+u+'.':'Now slide down to 0 mA.'}}}};

/* ---- automatic level control ---- */
WIDGETS.levelLoop=function(box){var cv=canvas(box,240),mode='onoff',K=4,man=50,running=false,passed=false,t,L,ua,I,on,hist,uh,SP=50,tried={};
 var r=row(box),mb={};[['man','Manual'],['onoff','On/off'],['p','Proportional'],['pi','P + integral']].forEach(function(x){mb[x[0]]=btn(r,x[1],function(){if(running)return;mode=x[0];upd()})});
 function sl(label,min,max,step,val,fmt,cb){var rr=el('div','wrow',null,box),id='lc'+Math.random().toString(36).slice(2,7);rr.innerHTML='<label for="'+id+'">'+label+'</label><input type="range" id="'+id+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+val+'"><output>'+fmt(val)+'</output>';var i=rr.querySelector('input'),o=rr.querySelector('output');i.oninput=function(){o.textContent=fmt(+i.value);cb(+i.value)};return rr}
 var kr=sl('Controller gain',1,10,1,4,function(v){return v},function(v){K=v}),mr=sl('Valve opening',0,100,5,50,function(v){return v+'%'},function(v){man=v});
 var r2=row(box),go=btn(r2,'Run 60 seconds',startRun,'pri'),st=stats(box,[['l','Level now'],['o','Off setpoint by'],['v','Valve open']]),m=msg(box);
 function upd(){for(var k in mb)mb[k].classList.toggle('on',k===mode);kr.style.display=(mode==='p'||mode==='pi')?'':'none';mr.style.display=mode==='man'?'':'none'}
 function reset(){t=0;L=50;ua=50;I=0;on=false;hist=[[0,50]];uh=[[0,50]]}
 function startRun(){if(running)return;reset();running=true;go.textContent='Running…';m.set('');tried[mode]=1;
  anim(cv,function(dt){if(!running)return false;var h=dt*4;t+=h;var d=t<15?50:70,e=SP-L,uc;
   if(mode==='man')uc=man;else if(mode==='onoff'){if(L<SP-3)on=true;else if(L>SP+3)on=false;uc=on?100:0}else{uc=50+K*e+(mode==='pi'?0.6*I:0);var cl=Math.max(0,Math.min(100,uc));if(mode==='pi'&&cl===uc)I+=e*h;uc=cl}
   ua+=(uc-ua)*Math.min(1,h/0.8);L=Math.max(0,Math.min(100,L+0.6*(ua-d)*h/10));hist.push([t,L]);uh.push([t,ua]);draw();
   if(t>=60){running=false;go.textContent='Run again';finish();return false}})}
 function finish(){var late=hist.filter(function(p){return p[0]>=45}),dev=Math.max.apply(null,late.map(function(p){return Math.abs(p[1]-SP)})),off=Math.abs(L-SP);
  var good=dev<=3&&mode!=='man';if(good)passed=true;
  m.set(mode==='onoff'?'On/off keeps cycling between 47% and 53%: the valve slams fully open, then fully shut. Hard on the valve, and never steady.':
   mode==='man'?(dev<=3?'Nice manual control, but you had to guess the valve position. Automatic control does this for you, all day and all night.':'In manual, the level drifts when the demand changes, unless someone keeps adjusting the valve.'):
   mode==='p'?(good?'The level settled close to the setpoint, '+off.toFixed(1)+'% away. A higher gain shrinks that offset, but makes the valve move harder.':'The level settled '+off.toFixed(1)+'% below the setpoint. That gap is called offset. Try a higher gain, or P + integral.'):
   (good?'Integral action kept adding to the valve opening until the offset was gone. The level is back on the setpoint.':'Not settled yet. Try a lower gain so it doesn\'t overshoot so much.'),good)}
 function draw(){var Pp=plot(cv,{x:[0,60],y:[0,100],xl:'time (s)',yl:'%'}),c=Pp.c;c.fillStyle=cssv('--good-bg');c.fillRect(Pp.X(0),Pp.Y(SP+3),Pp.W,Pp.Y(SP-3)-Pp.Y(SP+3));
  c.setLineDash([5,4]);c.strokeStyle=cssv('--muted');c.beginPath();c.moveTo(Pp.X(0),Pp.Y(SP));c.lineTo(Pp.X(60),Pp.Y(SP));c.stroke();c.beginPath();c.moveTo(Pp.X(15),Pp.Y(0));c.lineTo(Pp.X(15),Pp.Y(100));c.stroke();c.setLineDash([]);
  c.fillStyle=cssv('--muted');c.font='11px system-ui,sans-serif';c.textAlign='left';c.fillText('demand rises',Pp.X(15)+4,Pp.Y(94));c.fillText('setpoint',Pp.X(0)+4,Pp.Y(SP)-5);
  function line(a,col,w){c.strokeStyle=col;c.lineWidth=w;c.beginPath();a.forEach(function(p,i){var x=Pp.X(p[0]),y=Pp.Y(p[1]);if(i)c.lineTo(x,y);else c.moveTo(x,y)});c.stroke();c.lineWidth=1}
  if(uh)line(uh,cssv('--amber'),1.5);if(hist)line(hist,cssv('--accent'),2.5);
  c.fillStyle=cssv('--accent');c.fillText('level',Pp.X(48),Pp.Y(12));c.fillStyle=cssv('--amber');c.fillText('valve',Pp.X(48),Pp.Y(4));
  if(hist){st.l.textContent=L.toFixed(1)+'%';st.o.textContent=Math.abs(L-SP).toFixed(1)+'%';st.v.textContent=Math.round(ua)+'%'}}
 reset();upd();draw();
 return {check:function(){return passed?{ok:true}:{ok:false,msg:'Get the level to settle within 3% of the setpoint using automatic control. Try Proportional with a high gain, or P + integral.'}}}};

/* ---- why grids use high voltage ---- */
WIDGETS.lineLoss=function(box){var Vs=[33,132,275,400],P=1600,R=0.25,vi=-1,seen={};
 el('p','small','A simplified model: sending 1,600 MW down a line with a resistance of 0.25 Ω. Pick a voltage.',box);
 var r=row(box),bs=Vs.map(function(v,i){return btn(r,v+' kV',function(){vi=i;seen[i]=1;upd()})}),st=stats(box,[['i','Current'],['l','Power lost as heat'],['p','Share lost']]),barw=el('div','',null,box),m=msg(box);
 barw.style.cssText='height:16px;border-radius:8px;background:'+cssv('--soft2')+';overflow:hidden;margin-top:8px';var bar=el('div','',null,barw);bar.style.cssText='height:100%;width:0;transition:width .3s';
 function upd(){bs.forEach(function(b,i){b.classList.toggle('on',i===vi)});if(vi<0)return;var V=Vs[vi]*1000,I=P*1e6/V,loss=I*I*R/1e6,pc=loss/P*100;
  st.i.textContent=Math.round(I).toLocaleString('en-GB')+' A';st.l.textContent=(loss>=10?Math.round(loss):loss.toFixed(1))+' MW';st.p.textContent=pc.toFixed(pc<1?2:1)+'%';
  bar.style.width=Math.min(100,pc*2.5)+'%';bar.style.background=pc>5?cssv('--red'):cssv('--good-line');
  m.set(vi===3?'At 400 kV the current is low, so very little is wasted. That\'s why the grid uses such high voltages.':vi===0?'At low voltage the current is enormous, and the cables would waste a huge share as heat.':'Higher voltage, lower current, less heat in the cables.',vi===3?true:null)}
 return {check:function(){return seen[0]&&seen[3]?{ok:true}:{ok:false,msg:'Try both 33 kV and 400 kV.'}}}};

U({id:'th11',track:'theory',title:'Reading plant diagrams',icon:'⋈',color:'#378ADD',desc:'P&IDs: the drawings operators use to see how every pipe, pump, valve and instrument connects.',lessons:[
L('pd1','Pipes, symbols and lines',9,[
T(`<h3>The map of the plant</h3><p>A power station has thousands of pipes, pumps and valves. Operators can't see most of them from the control room, so they use drawings called <b>P&amp;IDs</b>: <b>piping and instrumentation diagrams</b>.</p><p>A P&amp;ID isn't drawn to scale. It shows <b>what connects to what</b>, using standard symbols, so anyone trained can read any drawing.</p>`),
W('tapLabels',{vb:'0 0 340 190',svg:TX.pid,spots:[[38,166,`Tank`,`Stores liquid. It's drawn as a simple outline, usually with a tag number such as T-101.`],[90,166,`Isolation valve`,`The bow-tie shape. It's used fully open or fully shut, for example to isolate part of a system for maintenance.`],[132,166,`Pump`,`A circle with a triangle. It pushes the liquid along. The triangle points the way the liquid flows.`],[174,166,`Check valve`,`Lets liquid flow one way only, so it can't run backwards into the pump when the pump stops.`],[222,166,`Control valve`,`A valve with an actuator on top. It can open part of the way, by exactly the amount the controller asks for.`],[276,166,`Heat exchanger`,`Passes heat from one fluid to another without them mixing, like the plant's coolers and steam generators.`],[74,52,`Level transmitter`,`An instrument bubble. L means level and T means transmitter: it measures the tank level and sends a signal.`],[150,60,`Level controller`,`The line through the middle means it's on a panel in the control room. It compares the level with its setpoint and works out how far to open the valve.`],[196,46,`Signal line`,`Dashed lines carry signals, not liquid. Here the level signal goes to the controller, and the controller's output goes to the valve.`]]},`Tap each numbered part of this simple P&ID.`,`Solid lines are pipes, dashed lines are signals, and every symbol has a standard meaning.`),
T(`<h3>Lines tell you what's moving</h3><ul><li>A <b>solid line</b> is a pipe carrying liquid, steam or gas. Arrows show the direction of flow.</li><li>A <b>dashed line</b> is a signal, usually electrical, between instruments.</li><li>Lines that cross without a dot or a joint <b>don't connect</b>. They just pass over each other on the page.</li></ul>`),
Q(`On a P&amp;ID, what does a dashed line usually show?`,[`A signal between instruments`,`A pipe that's empty`,`A pipe carrying steam`,`Something that's been removed`],0,`Solid lines carry fluid; dashed lines carry signals.`),
W('matchPairs',{pairs:[[TXS.valve,`Isolation valve`],[TXS.pump,`Pump`],[TXS.check,`Check valve`],[TXS.cv,`Control valve`],[TXS.bubble,`Instrument`],[TXS.signal,`Signal line`]],hint:`Tap a symbol on the left, then its name on the right.`},`Match each symbol to its name.`,`Those six symbols cover a surprising amount of any P&ID.`),
Q(`Why does a pump discharge often have a check valve?`,[`To stop flow running backwards when the pump stops`,'To control how fast the water flows when it runs','To measure the pressure the pump is making','To let trapped air out of the pipe when it starts'],0,`Without it, water could flow back through the pump, spinning it backwards or draining the system.`),
Q(`What's the difference between an isolation valve and a control valve?`,[`Isolation valves are fully open or shut; control valves can sit part-open`,'Isolation valves are bigger and always used on the main pipes','Control valves only work on steam; isolation valves only on water','There isn\'t one: they\'re two names for the same kind of valve'],0,`Control valves have an actuator that positions them precisely; isolation valves just open or shut.`),
T(`<h3>Key points</h3><ul><li><b>P&amp;IDs</b> show how every pipe, pump, valve and instrument connects. They aren't to scale.</li><li>Solid lines are <b>pipes</b>; dashed lines are <b>signals</b>.</li><li>Learn the core symbols: valve, pump, check valve, control valve, instrument bubble.</li></ul>`)]),
L('pd2','Instrument tags',8,[
T(`<h3>Reading the bubbles</h3><p>Every instrument on a P&amp;ID is drawn as a circle, or <b>bubble</b>, with a short code called a <b>tag</b>. The letters follow a standard pattern:</p><ul><li>The <b>first letter</b> is what's being measured: <b>T</b> temperature, <b>P</b> pressure, <b>L</b> level, <b>F</b> flow.</li><li>The <b>next letters</b> say what the instrument does: <b>I</b> indicator, <b>T</b> transmitter, <b>C</b> controller, <b>A</b> alarm, with <b>H</b> or <b>L</b> for high or low.</li></ul><p>A number such as 101 identifies the loop, so <b>PT-101</b> is pressure transmitter 101.</p>`),
Q(`What is a TI?`,[`A temperature indicator`,'A timer interlock',`A transmitter input`,'A turbine inlet sensor'],0,`T for temperature, I for indicator.`),
Q(`In the tag LAL, what does the final L mean?`,[`Low`,`Level`,`Loop`,`Local`],0,`Position matters. The first L is level (what's measured); the last L means low, so it's a level alarm, low.`),
W('tagBuilder',{},`Build the tag for each instrument.`,`First letter for what's measured, then letters for what it does.`),
T(`<h3>Where is it?</h3><p>The bubble's style shows where the instrument sits:</p><ul><li><b>No line</b> through the bubble: mounted out in the plant, next to the equipment.</li><li><b>A solid line</b> through the middle: on a panel or screen in the main control room.</li></ul><p>That matters to an operator: some readings you can only check by sending a field operator to look.</p>`),
Q(`A bubble has a solid line through the middle. Where's that instrument?`,[`In the main control room`,'Out in the plant, on a local panel','It has been removed from the plant','It\'s out of service and needs repair'],0,`A line through the bubble means it's on a control room panel or screen.`),
Q(`Which tag is a flow transmitter?`,[`FT`,`TF`,`FI`,`PT`],0,`F first (flow), then T (transmitter).`),
T(`<h3>Key points</h3><ul><li>Instruments are <b>bubbles with tags</b>.</li><li>First letter: <b>what's measured</b>. Next letters: <b>what it does</b>.</li><li>A line through the bubble means it's in the <b>control room</b>.</li></ul>`)]),
L('pd3','Following the flow: valve line-ups',10,[
T(`<h3>Lining up a system</h3><p>Before starting a pump, operators set every valve in the path to the right position. This is called a <b>line-up</b>. A wrong line-up can send water the wrong way, run a pump dry, or drain a system.</p><p>Operators trace the path on the P&amp;ID with a finger, valve by valve, before touching anything.</p>`),
W('pidLineUp',{},`Tap valves to open or shut them. Filled valves are shut. Then start the pump. Goal: water from tank A, through the heat exchanger, into tank B, with nothing wasted.`,`V1 and V2 open for the path through the heat exchanger, V3 shut so nothing bypasses it, V4 open to tank B, and the drain V5 shut.`),
T(`<h3>What the mistakes would do</h3><ul><li><b>Suction valve shut</b>: the pump runs dry and can be badly damaged.</li><li><b>No open path</b>: the pump is "dead-headed", churning the same water until it overheats.</li><li><b>Bypass open</b>: some water skips the heat exchanger, so it isn't cooled or heated properly.</li><li><b>Drain open</b>: water is lost, maybe somewhere it shouldn't go.</li></ul>`),
Q(`What happens if a pump starts with its suction valve shut?`,[`It runs dry and can be damaged`,'It pumps faster because there\'s nothing to push','Nothing: the pump just runs and waits for water','The suction valve opens itself when it senses flow'],0,`Pumps rely on the liquid flowing through them for cooling and lubrication.`),
T(`<h3>Isolating for maintenance</h3><p>To work safely on a pump or valve, it must be cut off from the rest of the system. Typically operators:</p><ul><li>shut the valves on <b>both sides</b> of the equipment</li><li><b>drain</b> and <b>vent</b> it so there's no trapped pressure</li><li><b>lock and tag</b> the valves so nobody opens them by mistake</li><li>hand over under a <b>permit to work</b>, so everyone knows it's safe</li></ul>`),
O(`Put the steps for isolating a pump for maintenance in order.`,[`Stop the pump`,`Shut the valves on both sides`,`Drain and vent the trapped water`,`Lock and tag the valves`,`Issue the permit to work`],`Stop it, isolate it, make it safe, stop anyone undoing it, then hand it over.`),
Q(`Why are isolation valves locked and tagged?`,[`So nobody opens them while people are working`,'To stop them rusting while they\'re not being used','To show they\'re new and haven\'t been tested yet','To make them easier to find during an emergency'],0,`A valve opened by mistake could send hot or pressurised water onto someone working on the equipment.`),
T(`<h3>Key points</h3><ul><li>A <b>line-up</b> sets every valve in the path before starting equipment.</li><li>Trace the path on the P&amp;ID first, valve by valve.</li><li>Isolation: shut both sides, drain and vent, lock and tag, then a permit to work.</li></ul>`)])
]});

U({id:'th12',track:'theory',title:'Instruments and control loops',icon:'◔',color:'#0F6E56',desc:'How the plant measures temperature, pressure, level and flow, and how automatic control keeps them steady.',lessons:[
L('ic1','Measuring the plant',9,[
T(`<h3>The control room's senses</h3><p>Operators never see the water in the reactor. Everything they know comes from <b>instruments</b>:</p><ul><li><b>Temperature</b>: thermocouples and resistance thermometers, whose electrical behaviour changes with heat.</li><li><b>Pressure</b>: a transmitter with a thin diaphragm that flexes as pressure pushes on it.</li><li><b>Level</b>: often measured by comparing the pressure at the bottom and top of a tank. More water, more pressure difference.</li><li><b>Flow</b>: measured from the pressure drop as fluid squeezes through a narrowing in the pipe.</li></ul>`),
Q(`How is the level in a tank often measured?`,[`From the pressure difference between the bottom and the top`,'By looking through a glass window in the side of the tank','By weighing the whole tank with load cells under its feet','With thermometers at different heights in the tank'],0,`A taller column of water pushes harder at the bottom, so pressure difference tracks level.`),
T(`<h3>4 to 20 milliamps</h3><p>Most transmitters send their reading as an electric current between <b>4 mA and 20 mA</b>. 4 mA means the bottom of the range and 20 mA means the top.</p><p>Why not start at 0? Because then a broken wire would look like a real reading of zero. With a "live zero" of 4 mA, anything well below 4 mA means the signal has failed, and the system can raise a fault alarm.</p>`),
W('signal420',{lo:0,hi:200,u:'bar',target:150},`A pressure transmitter with a range of 0 to 200 bar. Slide the signal and watch the display.`,`150 bar is three-quarters of the range, so 4 + 0.75 × 16 = 16 mA. And 0 mA is a fault, not zero pressure.`),
N(`A level transmitter has a range of 0 to 100%. It's sending 8 mA. What level is that?`,25,0.5,'%',`(8 − 4) ÷ 16 = 0.25 of the range, so 25%.`),
Q(`Why do signals start at 4 mA rather than 0 mA?`,[`So a broken wire shows up as a fault, not a false zero reading`,'To save electricity, because a lower current uses less power','Because a 0 mA signal is dangerous and could give a shock','It\'s just tradition from old instruments that are still used'],0,`The live zero lets the system tell "zero" from "failed".`),
T(`<h3>Key points</h3><ul><li>Instruments are the operators' only window into the plant.</li><li>Level and flow are often worked out from <b>pressure</b> measurements.</li><li><b>4 to 20 mA</b> signals: below 4 mA means a fault, not a real zero.</li></ul>`)]),
L('ic2','Redundancy and voting',8,[
T(`<h3>Never trust just one</h3><p>Any instrument can fail or drift. So the most important readings are measured by several separate <b>channels</b>, often four, each with its own sensor, wiring and power supply. This is called <b>redundancy</b>.</p><p>Every shift, operators do a <b>channel check</b>: they compare the channels with each other. If one reads differently from the rest, it's suspect.</p>`),
Q(`Three channels read 155 bar and one reads 139 bar. What's most likely?`,[`The odd channel has a fault`,`The pressure really is 139 bar`,`All four are wrong`,`The plant is about to trip`],0,`When three agree and one doesn't, suspect the odd one out, then get it checked.`),
T(`<h3>2 out of 4</h3><p>Safety systems use <b>voting</b>. A common scheme is <b>2 out of 4</b>: the reactor trips if any two channels see a problem.</p><ul><li>One faulty channel can't cause a <b>false trip</b> on its own.</li><li>One channel that has failed can't <b>stop</b> a real trip either, because the other three still vote.</li></ul>`),
W('voting',{},`Each channel can be tripped. Trip the reactor using as few channels as the 2-out-of-4 logic needs.`,`Two channels are enough. With 2 out of 4, a single fault is never enough to trip the plant, or to stop it tripping.`),
Q(`Why not just use 1 out of 1, a single channel?`,[`One fault could cause a false trip, or stop a real one`,'It would cost too much to fit and keep tested','It would be too slow to trip the reactor in time','One channel can\'t measure pressure accurately'],0,`A single channel is a single point of failure, either way.`),
T(`<h3>Diversity</h3><p>Redundancy protects against random faults. But four identical instruments could all fail the same way, for example from a design flaw. So designers also use <b>diversity</b>: measuring the same thing in <b>different ways</b>, with different equipment, so one weakness can't defeat them all.</p>`),
Q(`What does diversity mean in safety systems?`,[`Using different kinds of equipment to do the same job`,'Having four identical channels doing the same job','Employing a varied team of operators on each shift','Running different kinds of reactor on the same site'],0,`Different designs don't share the same hidden weaknesses.`),
T(`<h3>Key points</h3><ul><li><b>Redundancy</b>: several independent channels for important readings.</li><li><b>Channel checks</b> every shift spot drifting instruments.</li><li><b>2-out-of-4 voting</b>: no false trips from one fault, and no missed trips either.</li><li><b>Diversity</b>: different methods so one weakness can't defeat everything.</li></ul>`)]),
L('ic3','Automatic control loops',10,[
T(`<h3>Keeping things steady</h3><p>Hundreds of levels, pressures and temperatures in the plant are held steady automatically by <b>control loops</b>. Every loop has the same parts:</p><ul><li>the <b>setpoint</b>: the value you want</li><li>the <b>measurement</b>: what it actually is, from a transmitter</li><li>the <b>controller</b>: works out the error and decides what to do</li><li>the <b>final element</b>: usually a control valve, which makes the change</li></ul>`),
O(`Put a level control loop in order, starting from the tank.`,[`The transmitter measures the tank level`,`The controller compares it with the setpoint`,`The controller sends a new signal to the valve`,`The control valve opens or closes`,`The level changes, and the transmitter measures it again`],`It's a loop: the result is measured again, so the controller keeps correcting. That's called feedback.`),
W('levelLoop',{},`Control the level in a tank. Halfway through, the demand for water rises. Try each mode and compare.`,`On/off cycles, proportional leaves a small offset, and adding integral action brings the level right back to the setpoint.`),
T(`<h3>Three kinds of control</h3><ul><li><b>On/off</b>: the valve is fully open or fully shut. Simple, but the level keeps cycling and the valve slams.</li><li><b>Proportional</b>: the bigger the error, the more the valve moves. Smooth, but it settles with a small <b>offset</b> from the setpoint.</li><li><b>Proportional plus integral</b>: also adds up the error over time, and keeps adjusting until the offset is gone.</li></ul>`),
Q(`After a change, a proportional controller settles slightly away from the setpoint. What's that gap called?`,[`Offset`,`Overshoot`,`Drift`,`Deadband`],0,`Proportional control needs some error to hold the valve in its new position, so it leaves an offset.`),
Q(`What does adding integral action do?`,[`Removes the offset over time`,`Makes the valve open fully`,`Stops the loop working`,`Measures the flow`],0,`It keeps nudging the valve while any error remains.`),
Q(`An operator switches a controller to manual. What does that mean?`,[`The operator sets the valve position directly`,'The controller reacts faster to any change','The valve shuts and stays shut until reset','The setpoint changes to the operator\'s value'],0,`In manual, there's no automatic correction, so the operator must watch closely.`),
T(`<h3>Key points</h3><ul><li>Loops: <b>setpoint, measurement, controller, final element</b>, joined by feedback.</li><li><b>On/off</b> cycles; <b>proportional</b> leaves an offset; <b>integral</b> removes it.</li><li>In <b>manual</b>, the operator is the controller.</li></ul>`)])
]});

U({id:'th13',track:'theory',title:'Electrical systems',icon:'kV',color:'#BA7517',desc:'From the generator to the grid, how the plant powers itself, and what happens if the power goes.',lessons:[
L('ee1','From generator to grid',9,[
T(`<h3>Making electricity</h3><p>The turbine spins the <b>generator</b>, which produces three-phase alternating current at tens of thousands of volts. Before it leaves the site, a <b>generator transformer</b> steps it up to <b>400,000 volts (400 kV)</b> for the national grid.</p>`),
W('tapLabels',{vb:'0 0 340 220',svg:TX.sld,spots:[[36,92,`Generator`,`Turned by the turbine. It produces three-phase alternating current at tens of thousands of volts.`],[104,24,`Generator transformer`,`Steps the voltage up to 400,000 volts (400 kV) to send it out on the grid.`],[196,86,`Circuit breaker`,`A heavy-duty switch that can safely cut enormous currents. It connects the station to the grid, or disconnects it if there's a fault.`],[298,96,`The grid`,`The national transmission network. It carries the station's power to homes and businesses, and can also power the station when it's shut down.`],[118,108,`Unit transformer`,`Takes some of the power and steps it down to the voltages the plant's own equipment uses.`],[220,132,`Station switchboard`,`Busbars and breakers that share power out to the plant's pumps, fans and systems.`],[130,206,`Big pump motors`,`Pumps like the reactor coolant pumps and feedwater pumps. They use a lot of the station's own power.`],[66,186,`Batteries`,`Keep instruments, control systems and emergency lighting running without a break, even before the diesels start.`],[288,198,`Emergency diesel generator`,`Starts automatically if off-site power is lost, and powers the safety systems that keep the fuel cool.`]]},`This is a single-line diagram, the electrical version of a P&ID. Tap each part.`,`Generator, transformers, breakers and the grid, plus the station's own switchboard, batteries and diesels.`),
T(`<h3>Why such high voltage?</h3><p>Power = voltage × current. For the same power, a <b>higher voltage</b> means a <b>lower current</b>. And the heat wasted in cables depends on the <b>current squared</b>. So stepping up the voltage cuts the losses dramatically.</p>`),
W('lineLoss',{},`See how the voltage changes the losses.`,`Ten times the voltage means a tenth of the current, and only a hundredth of the heat lost in the cables.`),
Q(`If you double the transmission voltage for the same power, what happens to the heat lost in the cables?`,[`It falls to a quarter`,'It falls to one half','It rises to four times',`It stays the same`],0,`Current halves, and loss depends on current squared: ½ × ½ = ¼.`),
Q(`What does the generator transformer do?`,[`Steps the voltage up for the grid`,`Steps the voltage down for homes`,`Turns AC into DC`,`Stores electricity`],0,`It raises the voltage to 400 kV so the power can travel with low losses.`),
T(`<h3>Key points</h3><ul><li>Generator → <b>generator transformer</b> → breaker → <b>400 kV grid</b>.</li><li>High voltage means low current and <b>low losses</b>.</li><li>A <b>single-line diagram</b> shows the electrical system, like a P&amp;ID does for pipes.</li></ul>`)]),
L('ee2','Powering the plant itself',8,[
T(`<h3>A power station needs power</h3><p>A nuclear plant uses a lot of its own electricity: huge pumps, fans, instruments, computers and lighting. Its own supplies are called <b>essential</b> or <b>auxiliary</b> supplies.</p><p>When the plant is running, they come from its own generator through the <b>unit transformer</b>. When it's shut down, they come <b>from the grid</b>, called <b>off-site power</b>.</p>`),
Q(`When the reactor is shut down, where does the plant normally get its electricity?`,[`From the grid (off-site power)`,'From its own generator (on-site)','From solar panels on the roof','It doesn\'t need any electricity'],0,`With the turbine stopped, the plant imports power from the grid.`),
T(`<h3>Why it matters so much</h3><p>Even after shutdown, the fuel keeps producing <b>decay heat</b>. The pumps that remove it need electricity. That's why losing power is one of the most important events operators train for, and why there are several layers of backup.</p>`),
W('sortIt',{bins:[`Must keep running during a power cut`,`Can wait until power is back`],items:[[`Pumps that cool the reactor`,0],[`Control room instruments`,0],[`Emergency lighting`,0],[`Safety valves' control systems`,0],[`Office heating`,1],[`The visitor centre`,1],[`Car park lights`,1],[`Canteen ovens`,1]]},`Sort these loads by priority.`,`Cooling, instruments and safety systems come first. Everything else can wait.`),
Q(`Why do safety systems need power even after the reactor has shut down?`,[`To remove decay heat from the fuel`,'To keep making electricity for the grid',`To restart the chain reaction`,'They don\'t: the fuel cools by itself'],0,`The fuel keeps producing heat for days, and the cooling pumps need electricity.`),
T(`<h3>Key points</h3><ul><li>The plant powers itself from its <b>own generator</b> when running, and from the <b>grid</b> when shut down.</li><li>Cooling must continue after shutdown, so power for safety systems is vital.</li><li>Loads are prioritised: safety first.</li></ul>`)]),
L('ee3','When the power goes',10,[
T(`<h3>Loss of off-site power</h3><p>If the grid connection is lost, for example in a storm, the reactor trips automatically. Then the plant has to keep cooling the fuel with no outside help.</p><ul><li><b>Batteries</b> keep instruments and controls running instantly, with no break.</li><li><b>Emergency diesel generators</b> start automatically within seconds and power the safety systems.</li></ul>`),
O(`Put these events in order after the grid connection is lost.`,[`Off-site power is lost`,`The reactor trips and the control rods drop in`,`The emergency diesel generators start up`,`The diesels connect to the safety switchboards`,`Safety pumps run and keep removing decay heat`],`Trip first, then the diesels take over powering the cooling. Batteries cover instruments throughout.`),
Q(`What keeps the instruments working in the seconds before the diesels are running?`,[`Batteries`,`The turbine`,`The grid`,`Nothing, they go blank`],0,`Battery-backed supplies give instruments and controls power with no break at all.`),
T(`<h3>Lessons from Fukushima</h3><p>In 2011, a huge tsunami flooded the Fukushima Daiichi plant in Japan. The emergency diesels and much of the electrical equipment were knocked out, leaving the plant without AC power, called a <b>station blackout</b>. Without power to the cooling systems, several reactor cores overheated and were badly damaged.</p><p>Plants worldwide learned to protect backup power from flooding, add extra backup diesels in separate buildings, and keep mobile generators and pumps ready.</p>`),
Q(`What is a station blackout?`,[`Losing both off-site power and the emergency diesels`,'A power cut that only affects the offices and canteen','Turning the site lights off at night to save energy','A planned shutdown of the reactor for refuelling'],0,`With no AC power at all, only batteries and special backup systems remain.`),
Q(`What was a key lesson from Fukushima about electrical systems?`,[`Protect backup power from floods and have extra, separate backups`,'Diesel generators aren\'t needed if the grid is strong enough','Plants should switch their backups over to solar power only','Batteries should be removed, because they can catch fire in floods'],0,`The diesels worked until the flood reached them. Location and diversity of backups matter.`),
T(`<h3>Designed in at Hinkley Point C</h3><p>Hinkley Point C's design has several emergency diesels for each reactor, kept apart from each other, plus extra backup diesels in separate buildings for the worst case. The whole site also has flood defences.</p>`),
T(`<h3>Key points</h3><ul><li>Lose the grid: the reactor <b>trips</b>, <b>batteries</b> cover instruments, <b>diesels</b> power cooling.</li><li>A <b>station blackout</b> means no AC power at all.</li><li>Fukushima taught the world to protect and diversify backup power.</li></ul>`)])
]});

U({id:'th14',track:'theory',title:'Preventing human error',icon:'HP',color:'#D85A30',desc:'Why good people make mistakes, and the checking, briefing and speaking-up habits that catch them.',lessons:[
L('hp1','Why good people make mistakes',9,[
T(`<h3>Everyone makes mistakes</h3><p>Operators are highly trained, but they're human. Nuclear plants don't assume people will be perfect. They design ways of working that <b>catch errors before they matter</b>.</p><p>Errors come in a few types:</p><ul><li><b>Slip</b>: doing the wrong action without meaning to, like pressing the button next to the right one.</li><li><b>Lapse</b>: forgetting a step, often after being interrupted.</li><li><b>Mistake</b>: doing exactly what you meant to, but the plan was wrong because you misunderstood something.</li><li><b>Violation</b>: knowingly cutting corners or breaking a rule.</li></ul>`),
Q(`An operator is interrupted by a phone call and forgets to finish a step. What type of error is that?`,[`A lapse`,`A slip`,`A mistake`,`A violation`],0,`Forgetting is a lapse. Interruptions are one of the biggest causes.`),
Q(`An operator presses the switch next to the one they meant. What type of error?`,[`A slip`,`A lapse`,`A mistake`,`A violation`],0,`The intention was right; the action went wrong.`),
T(`<h3>Error traps</h3><p>Some situations make errors much more likely. Operators learn to spot these <b>error traps</b> and slow down when they see them: time pressure, distractions, tiredness, a task they've never done, a task they've done so often they stop thinking, and confusing procedures.</p>`),
W('sortIt',{bins:[`Error trap`,`Defence`],items:[[`Time pressure`,0],[`Being interrupted mid-task`,0],[`Tiredness at the end of a night shift`,0],[`Doing a task for the first time`,0],[`"I've done this loads of times"`,0],[`A confusing procedure step`,0],[`Peer check`,1],[`Pre-job brief`,1],[`Self-check with STAR`,1],[`Marking off procedure steps`,1],[`Three-way communication`,1],[`Stopping when unsure`,1]]},`Sort each into an error trap or a defence.`,`Spot the traps, then use the defences to catch what slips through.`),
Q(`Why is a very familiar task an error trap?`,[`People stop paying close attention`,`It's always done at night`,`Familiar tasks are more complicated`,`It isn't one`],0,`Overconfidence and autopilot lead to slips and skipped steps.`),
T(`<h3>Key points</h3><ul><li>Errors: <b>slips</b>, <b>lapses</b>, <b>mistakes</b> and <b>violations</b>.</li><li><b>Error traps</b> make errors more likely. Spot them and slow down.</li><li>The aim isn't perfect people; it's catching errors before they matter.</li></ul>`)]),
L('hp2','Self-checking and peer checking',10,[
T(`<h3>STAR, in detail</h3><p>Before any important action, operators <b>self-check</b> with <b>STAR</b>:</p><ul><li><b>Stop</b>: pause before acting.</li><li><b>Think</b>: what do I expect to happen? What if it doesn't?</li><li><b>Act</b>: touch the correct switch or valve, check its label, then operate it.</li><li><b>Review</b>: did I get the result I expected?</li></ul>`),
O(`Put STAR in order.`,[`Stop`,`Think`,`Act`,`Review`],`Stop, Think, Act, Review: a few seconds that stop most slips.`),
T(`<h3>Two pairs of eyes</h3><ul><li><b>Peer check</b>: before you act, a colleague watches and confirms you're about to operate the right thing, the right way.</li><li><b>Independent verification</b>: after something's done, a second person checks it separately, at a different time, without just taking your word for it.</li></ul><p>Both matter for critical steps, where one wrong move could cause a big problem.</p>`),
W('flipCards',{cards:[[`Self-check`,`STAR before every important action.`],[`Peer check`,`A colleague confirms before you act.`],[`Independent verification`,`A second person checks it separately afterwards.`],[`Place-keeping`,`Mark each procedure step as you do it, so you never lose your place.`],[`Three-way communication`,`Instruction, repeat back, confirm.`],[`Questioning attitude`,`If something seems wrong, it probably is. Ask.`]]},`Flip each card.`,`Six habits that make up an operator's error-prevention toolkit.`),
Q(`What's the difference between a peer check and independent verification?`,[`A peer check happens before the action; verification is a separate check afterwards`,'They\'re the same check, just with different names on the paperwork','Peer checks are only for new staff; experienced operators do verification','Verification is done by the same person, a second time, after the action'],0,`One catches errors as they're about to happen; the other catches anything that slipped through.`),
Q(`You're working through a long procedure and get interrupted. What protects you from skipping a step?`,[`Place-keeping: marking each step as it's done`,'Carrying on from where you remember you were','Asking whoever is nearby which step you were on','Skipping to the last step and checking the result'],0,`With steps marked off, you can see exactly where you stopped.`),
Q(`During STAR, you reach for a valve and the label doesn't match the procedure. What do you do?`,[`Stop and don't operate it until it's resolved`,`Operate it anyway, it's probably fine`,'Operate the valve next to it, which looks right','Ignore the label: labels are often out of date'],0,`A mismatch is exactly what STAR is there to catch. Stop and check.`),
T(`<h3>Key points</h3><ul><li><b>STAR</b> before every important action.</li><li><b>Peer check</b> before, <b>independent verification</b> after.</li><li><b>Place-keeping</b> stops lapses in long procedures.</li></ul>`)]),
L('hp3','Briefings, speaking up and learning',9,[
T(`<h3>Pre-job briefs</h3><p>Before an important task, the team holds a short <b>pre-job brief</b>. They talk through:</p><ul><li>what the task is and who does what</li><li>which steps are <b>critical</b>, where an error would matter most</li><li>what could go wrong, and the <b>worst</b> outcome</li><li>what they'll do if something unexpected happens</li></ul>`),
Q(`What's the main point of a pre-job brief?`,[`To think through what could go wrong before starting`,'To fill in time while the permits are being signed','To decide who does which job and when they have breaks','To have a record of who to blame if anything goes wrong'],0,`It's much easier to prevent a problem you've already imagined.`),
T(`<h3>Speak up, and stop when unsure</h3><p>A <b>questioning attitude</b> means noticing when something doesn't look right, and saying so, whoever you're talking to. Anyone can stop a job if they're unsure.</p><p>When in doubt, operators take <b>conservative decisions</b>: put the plant in a safe, stable state first, then work out what's going on.</p>`),
Q(`You're the newest person on shift and you think a senior operator is about to open the wrong valve. What should you do?`,[`Speak up straight away`,`Stay quiet, they're more experienced`,`Mention it after the shift`,`Open a different valve yourself`],0,`Speaking up is everyone's job. Experienced people make slips too.`),
Q(`An indication doesn't make sense and nobody knows why. What's the conservative decision?`,[`Put the plant in a safe, stable state, then investigate`,'Carry on as normal and keep a close eye on it','Raise power a little to see how the indication responds','Wait for it to go away before deciding what to do'],0,`Don't push on into the unknown. Make it safe first.`),
T(`<h3>Learning from mistakes</h3><p>After a task, teams hold a short <b>debrief</b>: what went well, what didn't, what to change. Plants also encourage people to report <b>near misses</b>, things that almost went wrong, so everyone can learn from them.</p><p>This only works in a <b>just culture</b>, where honest errors are reported without fear of blame. Hiding a mistake is far more dangerous than admitting it.</p>`),
Q(`Why do plants want people to report near misses?`,[`So everyone can fix the cause before it leads to a real event`,'To find out who made the mistake and punish them for it','Because the regulator needs the paperwork to be filled in','They don\'t: near misses are best kept within the team'],0,`Near misses are free lessons. The same causes, left unfixed, lead to real events.`),
T(`<h3>Key points</h3><ul><li><b>Pre-job briefs</b>: plan for what could go wrong.</li><li><b>Questioning attitude</b>: speak up, stop when unsure.</li><li><b>Conservative decisions</b>: safe and stable first.</li><li><b>Debriefs</b>, <b>near-miss reporting</b> and a <b>just culture</b> help everyone learn.</li></ul>`)])
]});

/* follow-up practice */
F('pd1',[Q(`What does P&amp;ID stand for?`,[`Piping and instrumentation diagram`,`Plant and instrument design`,`Pressure and isolation drawing`,`Pump and inlet diagram`],0,`It shows piping and instruments.`),Q(`Is a P&amp;ID drawn to scale?`,[`No, it shows connections, not sizes or distances`,`Yes, exactly`,`Only the pumps`,`Only in the control room`],0,`It's about what connects to what.`),Q(`Two lines cross on a P&amp;ID with no dot or joint. Are they connected?`,[`No, they just pass over each other`,`Yes`,`Only if one is dashed`,`Only on steam lines`],0,`Junctions are shown with a joint or dot.`),Q(`Which symbol is a circle with a triangle inside?`,[`A pump`,`A valve`,`A tank`,`An instrument`],0,`The triangle shows the direction of flow.`),Q(`What sits on top of a control valve symbol?`,[`An actuator`,`A pump`,`A tag number only`,`Nothing`],0,`The actuator moves the valve to the position the controller asks for.`)]);
F('pd2',[Q(`In an instrument tag, what does the first letter tell you?`,[`What's being measured`,`Who installed it`,`Where it is`,`How old it is`],0,`T, P, L or F: temperature, pressure, level or flow.`),Q(`What's a PT?`,[`A pressure transmitter`,`A pump timer`,`A power transformer`,`A pressure test`],0,`P for pressure, T for transmitter.`),Q(`What does LIC mean?`,[`Level indicating controller`,`Low instrument current`,`Level in channel`,`Line isolation check`],0,`L level, I indicating, C controller.`),Q(`What's TAH?`,[`Temperature alarm, high`,`Tank at height`,`Transmitter alarm`,`Temperature at half`],0,`T temperature, A alarm, H high.`),Q(`A bubble has no line through it. Where's the instrument?`,[`Out in the plant`,`In the control room`,`In the office`,`Nowhere, it's planned`],0,`No line means it's mounted locally, by the equipment.`)]);
F('pd3',[Q(`What is a valve line-up?`,[`Setting every valve in a path correctly before starting equipment`,`A queue of spare valves`,`Painting valves the same colour`,`Testing valves one by one`],0,`Get the path right first.`),Q(`What does "dead-headed" mean for a pump?`,[`It's pumping against a shut valve with nowhere to go`,`It's switched off`,`It's running backwards`,`It's brand new`],0,`It churns the same water and overheats.`),Q(`Why trace the path on the P&amp;ID before touching valves?`,[`To check every valve in the path is right`,`To make it look neat`,`Because valves are hidden`,`It isn't needed`],0,`Checking on paper first catches mistakes before they reach the plant.`),Q(`Why is equipment drained and vented before maintenance?`,[`To remove trapped liquid and pressure`,`To clean it`,`To cool the room`,`To test the drain`],0,`Trapped pressure could hurt someone when they open it up.`),Q(`What's a permit to work?`,[`A formal handover showing the equipment is safe to work on`,`A parking pass`,`A training certificate`,`An overtime form`],0,`It makes sure everyone knows the isolation is complete.`)]);
F('ic1',[Q(`What does a pressure transmitter use to sense pressure?`,[`A diaphragm that flexes`,`A float`,`A thermometer`,`A camera`],0,`The diaphragm's tiny movement is turned into a signal.`),Q(`How is flow often measured?`,[`From the pressure drop through a narrowing in the pipe`,`By counting drops`,`With a level gauge`,`From the pipe's temperature`],0,`Faster flow means a bigger pressure drop.`),N(`A transmitter's range is 0 to 200 bar. It reads 12 mA. What pressure is that?`,100,0.5,'bar',`12 mA is halfway between 4 and 20, so half of 200 = 100 bar.`),N(`A flow transmitter has a range of 0 to 400 kg/s. What current does it send at 100 kg/s?`,8,0.1,'mA',`100 is a quarter of the range: 4 + 0.25 × 16 = 8 mA.`),Q(`A signal reads 1 mA. What should the operator think?`,[`The signal has failed`,`The reading is zero`,`The reading is very high`,`Everything's normal`],0,`Below 4 mA means a fault, not a real value.`)]);
F('ic2',[Q(`What's redundancy?`,[`Several independent channels measuring the same thing`,`Equipment that isn't needed`,`Spare staff`,`Old instruments`],0,`If one fails, others still work.`),Q(`What's a channel check?`,[`Comparing redundant channels to spot one that's drifted`,`Changing the TV channel`,`Testing the alarms`,`Replacing a sensor`],0,`Operators do them every shift.`),Q(`In 2-out-of-4 logic, how many channels must trip to trip the reactor?`,[`2`,`1`,`3`,`4`],0,`Any two.`),Q(`With 2-out-of-4 logic, one channel fails and won't trip. Can the reactor still trip?`,[`Yes, the other three can still vote`,`No`,`Only manually`,`Only at night`],0,`Two of the remaining three are enough.`),Q(`Why use diversity as well as redundancy?`,[`So one shared weakness can't defeat every channel`,`To save money`,`To make training easier`,`To use up spare parts`],0,`Different designs fail in different ways.`)]);
F('ic3',[Q(`What's a setpoint?`,[`The value you want the controller to hold`,`Where the valve is fixed`,`The maximum reading`,`A type of alarm`],0,`The controller works to keep the measurement at the setpoint.`),Q(`Which part of a loop usually makes the change in the plant?`,[`The control valve (final element)`,`The transmitter`,`The setpoint`,`The P&amp;ID`],0,`It's the "muscle" of the loop.`),Q(`What's the main drawback of on/off control?`,[`It keeps cycling and the valve slams open and shut`,`It's too expensive`,`It can't be automatic`,`It never moves`],0,`Fine for a fridge, not for precise control.`),Q(`What's feedback in a control loop?`,[`The result is measured again and used to correct the next action`,`Complaints from operators`,`An alarm sound`,`A printed report`],0,`Measure, compare, correct, repeat.`),Q(`Turning up the gain of a proportional controller…`,[`reduces offset but can make it overshoot`,`removes the setpoint`,`stops the valve moving`,`has no effect`],0,`More aggressive, smaller offset, but more overshoot.`)]);
F('ee1',[Q(`What voltage does Hinkley Point C connect to the grid at?`,[`400 kV`,`230 V`,`11 kV`,`1 MV`],0,`400,000 volts.`),Q(`Power = voltage × …?`,[`current`,`resistance`,`frequency`,`time`],0,`P = V × I.`),Q(`Heat lost in cables depends on…`,[`the current squared`,`the voltage only`,`the colour of the cable`,`the time of day`],0,`Loss = I²R.`),N(`A line carries 2,000 A. If the voltage is doubled for the same power, what's the new current?`,1000,1,'A',`Double the voltage, half the current.`),Q(`What's a single-line diagram?`,[`A simplified drawing of an electrical system`,`A one-page procedure`,`A pipe drawing`,`A graph`],0,`It's the electrical version of a P&amp;ID.`)]);
F('ee2',[Q(`When the plant is running, where do its own supplies come from?`,[`Its own generator through the unit transformer`,`Batteries only`,`Diesels`,`The visitor centre`],0,`It uses some of what it makes.`),Q(`What's off-site power?`,[`Electricity from the grid`,`Power from the diesels`,`Solar panels`,`Batteries`],0,`Power supplied from outside the station.`),Q(`Why is losing power a big deal after shutdown?`,[`Cooling pumps need it to remove decay heat`,`The lights go off`,`The turbine stops`,`It isn't`],0,`Decay heat keeps coming for days.`),Q(`Which load comes first in a power cut?`,[`Reactor cooling pumps`,`Office heating`,`Car park lights`,`Canteen ovens`],0,`Safety first.`),Q(`What's the unit transformer for?`,[`Stepping power down for the plant's own equipment`,`Stepping power up for the grid`,`Storing power`,`Measuring power`],0,`It feeds the station's switchboards.`)]);
F('ee3',[Q(`What starts automatically if off-site power is lost?`,[`The emergency diesel generators`,`The turbine`,`The visitor centre`,`Nothing`],0,`Within seconds.`),Q(`What happens to the reactor when the grid is lost?`,[`It trips automatically`,`It speeds up`,`It keeps running normally`,`It's refuelled`],0,`The rods drop in and the chain reaction stops.`),Q(`What knocked out the backup power at Fukushima?`,[`A tsunami flooding the site`,`A cyber attack`,`A fire in the canteen`,`Running out of diesel`],0,`The flood reached the diesels and electrical equipment.`),Q(`Why are backup diesels kept in separate buildings?`,[`So one event can't knock them all out`,`To save space`,`They're noisy`,`For security passes`],0,`Separation is a defence against floods, fires and other hazards.`),Q(`What gives instruments power with no break at all?`,[`Batteries`,`Diesels`,`The grid`,`The turbine`],0,`Diesels take a few seconds to start; batteries are instant.`)]);
F('hp1',[Q(`Doing exactly what you planned, but the plan was wrong, is a…`,[`mistake`,`slip`,`lapse`,`violation`],0,`The thinking went wrong, not the action.`),Q(`Knowingly skipping a step to save time is a…`,[`violation`,`slip`,`lapse`,`mistake`],0,`A deliberate shortcut.`),Q(`Which of these is an error trap?`,[`Being interrupted mid-task`,`A peer check`,`A pre-job brief`,`Place-keeping`],0,`Interruptions cause lapses.`),Q(`What should you do when you spot an error trap?`,[`Slow down and use extra checks`,`Work faster to get it done`,`Ignore it`,`Leave the task`],0,`Recognise it, then defend against it.`),Q(`What's the aim of human performance tools?`,[`Catch errors before they matter`,`Make people perfect`,`Find someone to blame`,`Speed jobs up`],0,`People will slip; the tools stop slips becoming events.`)]);
F('hp2',[Q(`What does the R in STAR stand for?`,[`Review`,`Repeat`,`Reset`,`Report`],0,`Did you get the result you expected?`),Q(`What happens in the Think step?`,[`You decide what you expect to happen, and what you'll do if it doesn't`,`You daydream`,`You read the whole manual`,`You ask permission`],0,`Predict the result before you act.`),Q(`When does a peer check happen?`,[`Before the action`,`A day later`,`Only during tests`,`Never`],0,`A colleague confirms you're about to do the right thing.`),Q(`What's place-keeping?`,[`Marking each procedure step as it's done`,`Saving a seat`,`Keeping tools tidy`,`Labelling valves`],0,`You always know where you are, even after an interruption.`),Q(`Why must independent verification be done separately?`,[`So the checker doesn't just take your word for it`,`To save time`,`Because it's easier`,`So nobody sees`],0,`A genuinely separate check catches what you missed.`)]);
F('hp3',[Q(`Which question belongs in a pre-job brief?`,[`What's the worst thing that could go wrong?`,`What's for lunch?`,`Who's to blame?`,`How quickly can we finish?`],0,`Plan for the worst before you start.`),Q(`Who can stop a job if they're unsure?`,[`Anyone`,`Only the manager`,`Only engineers`,`Nobody`],0,`Everyone has the right and duty to stop.`),Q(`What's a near miss?`,[`Something that almost went wrong`,`A late arrival`,`A missed phone call`,`A test that passed`],0,`Reporting them prevents real events.`),Q(`What's a just culture?`,[`Honest errors can be reported without fear of blame`,`Nobody makes mistakes`,`Everyone is punished equally`,`There are no rules`],0,`People report more, so everyone learns more.`),Q(`What does a conservative decision mean in the control room?`,[`Choose the safest, most stable option when unsure`,`Do nothing at all`,`Vote on it`,`Wait for the next shift`],0,`Safe and stable first, then work out what's happening.`)]);

